{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": ["p7", "p6"],
      "avoid": [],
      "markers": [
        {"part": "p7", "label": "სიმაღლის რეგულირების ღილაკი", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p7", "type": "move", "dir": "toward"}
      ],
      "tools": [],
      "warn": "ფოტოზე სავარძლის ქვეშ მდებარე ყვითელი ღილაკი შეესაბამება p7-ს და არა წონის დასტასთან მდებარე p2-ს. რეგულირების ზუსტი მექანიზმი ფოტოდან არ დასტურდება; დაჯდომამდე დარწმუნდი, რომ სავარძელი მყარად დაფიქსირდა."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": ["p2", "p3"],
      "avoid": [],
      "markers": [
        {"part": "p2", "label": "წონის შესარჩევი ქინძისთავი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "სამიზნედ შერჩეულია წონის დასტის მარჯვენა მხარეს ხილული p2 და არა სავარძლის ქვემოთ მდებარე p7. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები სრულად დაშვებულია; თითები ფილებს შორის არ მოათავსო."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "მოჭიდება მოხრილ ბოლოებთან", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p6", "p4", "p5", "p1"],
      "avoid": [],
      "markers": [
        {"part": "p6", "label": "სავარძელი", "tone": "brand"},
        {"part": "p4", "label": "მარცხენა დამაფიქსირებელი ბალიში", "tone": "brand"},
        {"part": "p5", "label": "მარჯვენა დამაფიქსირებელი ბალიში", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": null
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "იმოძრავე კონტროლირებულად", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "down"},
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "არ ჩამოწიო სახელური კისრის უკან და არ გამოიყენო სხეულის ქნევა. მითითებული 2 წამი ინსტრუქციის ტემპია და არა ფოტოდან დადგენილი მონაცემი."
    }
  ],
  "unknown_parts": []
}
